#!/usr/bin/env bash
# Compiles kubeport-ffi, generates the Swift bindings and assembles app/KubeportFFI.xcframework.
# Outputs (ignored by git):
#   app/KubeportFFI.xcframework           static library + headers + modulemap
#   app/Sources/Kubeport/Generated/       Swift code generated by UniFFI
# ARCHS: the Mac architectures to build, "arm64" and/or "x86_64" (default: this Mac's).
# PROFILE: the Cargo profile (default: release, the shipped one; dev skips LTO, for tests).
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GEN="$ROOT/target/uniffi"
XCF="$ROOT/app/KubeportFFI.xcframework"
SWIFT_OUT="$ROOT/app/Sources/Kubeport/Generated"

cd "$ROOT"
# Same minimum macOS as the app (app/Package.swift).
export MACOSX_DEPLOYMENT_TARGET=14.0
PROFILE="${PROFILE:-release}"
case "$PROFILE" in
  release) OUT=release ;;
  dev) OUT=debug ;;
  *) echo "unknown profile: $PROFILE" >&2; exit 1 ;;
esac
LIBS=()
for arch in ${ARCHS:-$(uname -m)}; do
  case "$arch" in
    arm64) triple=aarch64-apple-darwin ;;
    x86_64) triple=x86_64-apple-darwin ;;
    *) echo "unknown arch: $arch" >&2; exit 1 ;;
  esac
  rustup target add "$triple" >/dev/null
  cargo build --profile "$PROFILE" --locked -p kubeport-ffi --target "$triple"
  LIBS+=("target/$triple/$OUT/libkubeport_ffi.a")
done

rm -rf "$GEN" "$XCF" "$SWIFT_OUT"
mkdir -p "$GEN/include" "$SWIFT_OUT"
# One static library for every architecture.
lipo -create "${LIBS[@]}" -output "$GEN/libkubeport_ffi.a"
cargo run --profile "$PROFILE" --locked -q -p kubeport-ffi --bin uniffi-bindgen -- \
  "${LIBS[0]%.a}.dylib" "$GEN" \
  --swift-sources --headers --modulemap \
  --module-name kubeport_ffiFFI --modulemap-filename module.modulemap

mv "$GEN"/*.h "$GEN/module.modulemap" "$GEN/include/"
mv "$GEN"/*.swift "$SWIFT_OUT/"

xcodebuild -create-xcframework \
  -library "$GEN/libkubeport_ffi.a" \
  -headers "$GEN/include" \
  -output "$XCF" >/dev/null
echo "$XCF"
